<?php
use app\services\{Ui,Organization};use yii\helpers\Html;
$this->title='Universitet tuzilmasi';$super=Yii::$app->user->identity->role==='superadmin';
$map=array_column($rows,null,'id');$roots=[];$faculties=[];$departments=[];$units=[];
foreach($rows as $r){if($r['kind']==='university')$roots[]=$r;elseif(empty($r['type_verified']) || $r['kind']==='unit')$units[]=$r;elseif($r['kind']==='faculty')$faculties[]=$r;elseif($r['kind']==='department')$departments[]=$r;}
$universityId=(int)Yii::$app->request->get('university',0);$facultyId=(int)Yii::$app->request->get('faculty',0);
$labels=Organization::labels($rows);$facultyChoices=[];foreach($faculties as $f)if(!$universityId || (int)$f['parent_id']===$universityId)$facultyChoices[$f['id']]=$labels[$f['id']];
if($facultyId && !isset($facultyChoices[$facultyId]))$facultyId=0;
$this->registerCssFile(Yii::$app->request->baseUrl.'/css/organization.css?v=3');
$editLink=fn($id)=>Html::a('Tahrirlash',['admin/structure-edit','id'=>$id],['class'=>'button small secondary']);
$status=static function($row)use($rows){$blocked=Organization::blockedBy((int)$row['id'],$rows);return '<span class="badge '.($blocked?'rejected':'approved').'">'.($blocked?'Bloklangan':'Faol').'</span>';};
?>
<div class="page-heading"><div><span class="eyebrow">TASHKILOT BOSHQARUVI</span><h1>Universitet tuzilmasi</h1><p>Fakultetlar va kafedralar alohida. Har bir kafedraning fakulteti va universiteti ko‘rsatiladi. Boshqa tuzilmalar “Bo‘limlar”da.</p></div><?php if($super): ?><div class="actions"><?= Html::a('Barchasini o‘chirish',['admin/delete-all','scope'=>'structure'],['class'=>'button danger']) ?></div><?php endif ?></div>
<section class="card"><?= Html::beginForm(['admin/structure'],'get',['class'=>'filters']) ?><?= Ui::select('Universitet','university',$universityId,[''=>'Barcha universitetlar']+array_column($roots,'name','id')) ?><?= Ui::select('Fakultet','faculty',$facultyId,[''=>'Barcha fakultetlar']+$facultyChoices) ?><button class="button secondary">Ko‘rsatish</button><?= Html::endForm() ?><div class="organization-section-links"><a href="#universities">Universitetlar</a><a href="#faculties">Fakultetlar</a><a href="#departments">Kafedralar</a><a href="#units">Bo‘limlar</a></div></section>
<?php $pending=count(array_filter($rows,fn($r)=>empty($r['type_verified'])));if($pending): ?><div class="alert warning"><?= $pending ?> ta tuzilma yozuvining turi tasdiqlanmagan. Ular “Bo‘limlar”da belgilangan. HEMIS’dan tuzilmani qayta import qiling — mavjud ID va xodimlar saqlanib, turlar tuzatiladi. Yoki Tahrirlash orqali turini qo‘lda tanlang.</div><?php endif ?>
<section class="card" id="universities"><div class="card-heading"><div><span class="eyebrow">01 · UNIVERSITET</span><h2>Universitetlar</h2></div><?php if($super): ?><?= Html::a('+ Universitet yaratish',['admin/structure-edit','kind'=>'university'],['class'=>'button small']) ?><?php endif ?></div>
<?php $visible=array_filter($roots,fn($r)=>!$universityId || (int)$r['id']===$universityId);if(!$visible): ?><?= Ui::empty('Universitet kiritilmagan.') ?><?php else: ?><div class="table-wrap"><table><thead><tr><th>Universitet nomi</th><th>Fakultetlar</th><th>Holat</th><th>Amal</th></tr></thead><tbody><?php foreach($visible as $r): ?><tr><td><b><?= Ui::h($r['name']) ?></b></td><td><?= count(array_filter($faculties,fn($f)=>(int)$f['parent_id']===(int)$r['id'])) ?></td><td><?= $status($r) ?></td><td><?= $editLink($r['id']) ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>
<section class="card" id="faculties"><div class="card-heading"><div><span class="eyebrow">02 · FAKULTET</span><h2>Fakultetlar</h2></div><?php if($super): ?><?= Html::a('+ Fakultet yaratish',['admin/structure-edit','kind'=>'faculty','parent_id'=>$universityId?:null],['class'=>'button small']) ?><?php endif ?></div>
<?php $visible=array_filter($faculties,fn($f)=>(!$universityId || (int)$f['parent_id']===$universityId) && (!$facultyId || (int)$f['id']===$facultyId));if(!$visible): ?><?= Ui::empty('Tanlangan universitet uchun fakultet topilmadi.') ?><?php else: ?><div class="table-wrap"><table><thead><tr><th>Fakultet nomi</th><th>Tegishli universitet</th><th>Kafedralar</th><th>Holat</th><th>Amal</th></tr></thead><tbody><?php foreach($visible as $r): ?><tr><td><b><?= Ui::h($r['name']) ?></b></td><td><?= Ui::h($map[$r['parent_id']]['name']??'Universitet biriktirilmagan') ?></td><td><?= Html::a((string)count(array_filter($departments,fn($d)=>(int)$d['parent_id']===(int)$r['id'])).' ta kafedra',['admin/structure','faculty'=>$r['id'],'university'=>$r['parent_id'],'#'=>'departments'],['class'=>'text-link']) ?></td><td><?= $status($r) ?></td><td><?= $editLink($r['id']) ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>
<section class="card" id="departments"><div class="card-heading"><div><span class="eyebrow">03 · KAFEDRA</span><h2>Kafedralar</h2></div><?php if($super): ?><?= Html::a('+ Kafedra yaratish',['admin/structure-edit','kind'=>'department','parent_id'=>$facultyId?:null],['class'=>'button small']) ?><?php endif ?></div>
<?php $visible=array_filter($departments,function($d)use($map,$universityId,$facultyId){$f=$map[$d['parent_id']]??null;return (!$facultyId || (int)$d['parent_id']===$facultyId) && (!$universityId || (($f['kind']??'')==='university'?(int)$f['id']:(int)($f['parent_id']??0))===$universityId);});if(!$visible): ?><?= Ui::empty('Tanlangan fakultet uchun kafedra topilmadi.') ?><?php else: ?><div class="table-wrap"><table><thead><tr><th>Kafedra nomi</th><th>Tegishli fakultet</th><th>Universitet</th><th>Holat</th><th>Amal</th></tr></thead><tbody><?php foreach($visible as $r):$f=$map[$r['parent_id']]??null;$u=($f['kind']??'')==='university'?$f:($map[$f['parent_id']??null]??null); ?><tr><td><b><?= Ui::h($r['name']) ?></b></td><td><b><?= Ui::h($f && $f['kind']==='faculty' && !empty($f['type_verified'])?$f['name']:(!empty($r['needs_review'])?'Fakultetni aniqlashtiring':'Universitetga qarashli')) ?></b></td><td><?= Ui::h($u['name']??'Universitet biriktirilmagan') ?></td><td><?= $status($r) ?></td><td><?= $editLink($r['id']) ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>

<section class="card" id="units"><div class="card-heading"><div><span class="eyebrow">04 · BO‘LIM</span><h2>Bo‘limlar</h2></div><?php if($super): ?><?= Html::a('+ Bo‘lim yaratish',['admin/structure-edit','kind'=>'unit','parent_id'=>$universityId?:null],['class'=>'button small']) ?><?php endif ?></div><p class="muted">Buxgalteriya, boshqarma, markaz, dekanat va boshqa tuzilmalar. Turi aniqlanmagan yozuvlar alohida belgilangan.</p>
<?php $visible=array_filter($units,function($r)use($rows,$universityId,$facultyId){$chain=Organization::lineage((int)$r['id'],$rows);return (!$universityId || (int)($chain['university']['id']??0)===$universityId) && (!$facultyId || (int)($chain['faculty']['id']??0)===$facultyId);});if(!$visible): ?><?= Ui::empty('Bo‘limlar topilmadi.') ?><?php else: ?><div class="table-wrap"><table><thead><tr><th>Bo‘lim nomi</th><th>Yuqori tuzilma</th><th>Universitet</th><th>Turi / tekshiruv</th><th>Holat</th><th>Amal</th></tr></thead><tbody><?php foreach($visible as $r):$chain=Organization::lineage((int)$r['id'],$rows); ?><tr><td><b><?= Ui::h($r['name']) ?></b></td><td><?= Ui::h($map[$r['parent_id']]['name']??'Yo‘q') ?></td><td><?= Ui::h($chain['university']['name']??'Yo‘q') ?></td><td><span class="badge <?= empty($r['type_verified'])?'returned':'approved' ?>"><?= empty($r['type_verified'])?'Turini tekshiring':'Bo‘lim' ?></span><?php if($r['classification_note']): ?><small><?= Ui::h($r['classification_note']) ?></small><?php endif ?></td><td><?= $status($r) ?></td><td><?= $editLink($r['id']) ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>
